export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  const rawLower = Number.isFinite(minDistance) ? minDistance : -Infinity;
  const rawUpper = Number.isFinite(maxDistance) ? maxDistance : Infinity;
  let lower = Math.min(rawLower, rawUpper);
  let upper = Math.max(rawLower, rawUpper);

  // Keep radius non-negative and valid even when callers pass nonsense.
  if (!Number.isFinite(lower)) lower = 0;
  if (!Number.isFinite(upper)) upper = lower;
  if (upper < lower) upper = lower;

  const clampRadius = (radius: number): number => {
    if (!Number.isFinite(radius)) return Number.isFinite(upper) ? (Number.isFinite(lower) ? Math.max(lower, Math.min(upper, (lower + upper) / 2)) : lower) : upper;
    return Math.min(upper, Math.max(lower, radius));
  };

  const limits = { lowerRadiusLimit: lower, upperRadiusLimit: upper };
  const disposeLimits = setCameraLimits(camera, limits, scene);

  camera.lowerRadiusLimit = lower;
  camera.upperRadiusLimit = upper;

  const initialRadius = camera.radius;
  if (!Number.isFinite(initialRadius) || initialRadius < lower || initialRadius > upper) {
    camera.radius = clampRadius(initialRadius);
    camera.inertialRadiusOffset = 0;
  }

  camera._clampToLimits?.();

  const disposeControls = attachControl(camera, canvas, scene, { keyboard: false });

  return () => {
    disposeControls();
    disposeLimits();
  };
}
```
