import { attachControl, setCameraLimits } from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function attachLimitedOrbit(camera: ArcRotateCamera, canvas: HTMLCanvasElement, scene: SceneContext, minDistance: number, maxDistance: number): () => void {
  const lower = Math.min(minDistance, maxDistance);
  const upper = Math.max(minDistance, maxDistance);

  const clampRadius = (radius: number): number => {
    if (!Number.isFinite(radius)) {
      return Number.isFinite(upper) ? upper : Number.isFinite(lower) ? lower : 0;
    }
    return Math.min(upper, Math.max(lower, radius));
  };

  const initialRadius = camera.radius;
  const disposeLimits = setCameraLimits(camera, { lowerRadiusLimit: lower, upperRadiusLimit: upper }, scene);

  camera._clampToLimits?.();

  if (!Number.isFinite(initialRadius) || initialRadius < lower || initialRadius > upper) {
    camera.radius = clampRadius(camera.radius);
    camera.inertialRadiusOffset = 0;
