  const disposeControls = attachControl(camera, canvas, scene, { keyboard: false });

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    try {
      disposeControls();
    } finally {
      disposeLimits();
    }
  };
}
