import { attachControl, setCameraLimits } from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function attachLimitedOrbit(...): () => void {
  const lower = Math.min(minDistance, maxDistance);
  const upper = Math.max(minDistance, maxDistance);
  const clamp = (r: number) => Math.min(upper, Math.max(lower, r));

  const disposeLimits = setCameraLimits(camera, { lowerRadiusLimit: lower, upperRadiusLimit: upper }, scene);
  camera.lowerRadiusLimit = lower;
  camera.upperRadiusLimit = upper;

  if (camera.radius < lower || camera.radius > upper) {
    camera.radius = clamp(camera.radius);
    camera.inertialRadiusOffset = 0;
  }

  const disposeControls = attachControl(camera, canvas, scene, { keyboard: false });

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    try { disposeControls(); } finally { disposeLimits(); }
  };
}
```
